import http from 'node:http';

const port = 3001;

function createDemoFileBuffer() {
  return Buffer.from(
    [
      'application/octet-stream download demo',
      '',
      'This file is generated by download-pic-server.js.',
      'HTTP sends the response body as bytes.',
      'Content-Type tells the client how to interpret those bytes.',
      ''
    ].join('\n'),
    'utf8'
  );
}

function createDemoPngBuffer() {
  const base64Png =
    '';

  return Buffer.from(base64Png, 'base64');
}

function sendHomePage(res) {
  res.writeHead(200, {
    'Content-Type': 'text/html; charset=utf-8'
  });

  res.end(`<!doctype html>
<html lang="zh-CN">
  <head>
    <meta charset="utf-8" />
    <title>application/octet-stream download demo</title>
  </head>
  <body>
    <h1>application/octet-stream 下载 demo</h1>
    <ul>
      <li><a href="/download">下载文件: Content-Length</a></li>
      <li><a href="/download-stream">下载文件: chunked/stream</a></li>
      <li><a href="/download-image">下载图片: image/png</a></li>
    </ul>
  </body>
</html>`);
}

function sendOctetStreamDownload(res) {
  const fileBuffer = createDemoFileBuffer();

  res.writeHead(200, {
    'Content-Type': 'application/octet-stream',
    'Content-Disposition': 'attachment; filename="demo-file.txt"',
    'Content-Length': fileBuffer.length
  });

  res.end(fileBuffer);
}

function sendImageDownload(res) {
  const imageBuffer = createDemoPngBuffer();

  res.writeHead(200, {
    'Content-Type': 'image/png',
    'Content-Disposition': 'attachment; filename="demo-image.png"',
    'Content-Length': imageBuffer.length
  });

  res.end(imageBuffer);
}

function sendOctetStreamDownloadByChunk(res) {
  res.writeHead(200, {
    'Content-Type': 'application/octet-stream',
    'Content-Disposition': 'attachment; filename="demo-stream-file.txt"'
  });

  const chunks = [
    Buffer.from('chunk 1: hello\n', 'utf8'),
    Buffer.from('chunk 2: application/octet-stream\n', 'utf8'),
    Buffer.from('chunk 3: no Content-Length, Node will use chunked\n', 'utf8')
  ];

  let index = 0;
  const timer = setInterval(() => {
    if (index >= chunks.length) {
      clearInterval(timer);
      res.end();
      return;
    }

    res.write(chunks[index]);
    index += 1;
  }, 500);
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (req.method !== 'GET') {
    res.writeHead(405, {
      'Content-Type': 'text/plain; charset=utf-8',
      Allow: 'GET'
    });
    res.end('Method Not Allowed');
    return;
  }

  if (url.pathname === '/') {
    sendHomePage(res);
    return;
  }

  if (url.pathname === '/download') {
    sendOctetStreamDownload(res);
    return;
  }

  if (url.pathname === '/download-image') {
    sendImageDownload(res);
    return;
  }

  if (url.pathname === '/download-stream') {
    sendOctetStreamDownloadByChunk(res);
    return;
  }

  res.writeHead(404, {
    'Content-Type': 'text/plain; charset=utf-8'
  });
  res.end('Not Found');
});

server.listen(port, '127.0.0.1', () => {
  console.log(`download demo server listening on http://localhost:${port}`);
  console.log(`open http://localhost:${port}/download to download a file`);
  console.log(`open http://localhost:${port}/download-image to download an image`);
  console.log(`open http://localhost:${port}/download-stream to download by chunks`);
});
